import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '../../../ui/overlays/alert-dialog';
import { Button } from '../../../ui/actions/button';
import { useFilterPanelLocaleV2 } from '../i18n';

interface DeleteTemplateDialogPropsV2 {
  open: boolean;
  templateName: string;
  onClose: () => void;
  onConfirm: () => void;
}

export function DeleteTemplateDialog({
  open,
  templateName,
  onClose,
  onConfirm,
}: DeleteTemplateDialogPropsV2) {
  const locale = useFilterPanelLocaleV2();
  return (
    <AlertDialog open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <AlertDialogContent>
        <AlertDialogHeader className="text-start">
          <AlertDialogTitle>{locale.deleteDialogTitle}</AlertDialogTitle>
          <AlertDialogDescription>
            {locale.deleteDialogDescription(templateName)}
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel onClick={onClose}>{locale.cancelLabel}</AlertDialogCancel>
          <Button variant="destructive" onClick={onConfirm}>
            {locale.deleteLabel}
          </Button>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

import { memo } from 'react';
import { Tabs, TabsList, TabsTrigger } from '../../../ui/actions/tabs';
import { AsyncSelect } from '../../../patterns/async-select';
import { MultiSelect } from '../../../patterns/multi-select';
import { DatePicker, DateRangePicker, type DateValue, type DateRange } from '../../date-picker';
import { cn } from '../../../../lib/utils';
import type {
  AdvancedFilterConfigV2,
  DatePickerFilterConfigV2,
  DateRangePickerFilterConfigV2,
  FilterConfigV2,
  FilterValueV2,
  MultiSelectFilterConfigV2,
  SelectFilterConfigV2,
  TabFilterConfigV2,
  TreeMultipleSelectFilterConfig,
  TreeSelectFilterConfig,
} from '../types';
import { TreeMultipleSelect, TreeSelect } from '../../../patterns/tree-select';

// ---------------------------------------------------------------------------
// Shared renderer prop shape
// ---------------------------------------------------------------------------

type RendererProps<TFilter> = {
  filter: TFilter;
  value: FilterValueV2;
  onChange: (value: FilterValueV2) => void;
  layout: 'row' | 'column';
};

// ---------------------------------------------------------------------------
// Per-type renderer components
// ---------------------------------------------------------------------------

function TabsFilter({ filter, value, onChange }: RendererProps<TabFilterConfigV2>) {
  return (
    <Tabs
      value={value as string}
      onValueChange={(v) => {
        onChange(v);
        filter.onChange?.(v);
      }}
    >
      <TabsList>
        {filter.options.map((option) => (
          <TabsTrigger disabled={filter.disable} key={option.value} value={option.value}>
            {option.label}
          </TabsTrigger>
        ))}
      </TabsList>
    </Tabs>
  );
}

function AsyncSelectFilter({
  filter,
  value,
  onChange,
  layout,
}: RendererProps<SelectFilterConfigV2>) {
  if (!filter.asyncSelectProps) return null;
  return (
    <AsyncSelect
      {...filter.asyncSelectProps}
      value={value as string}
      onChange={(v) => onChange(v)}
      className={cn(layout === 'row' ? 'w-50' : 'w-full', filter.asyncSelectProps.className)}
      disabled={filter.disable}
    />
  );
}

function MultiSelectFilter({
  filter,
  value,
  onChange,
  layout,
}: RendererProps<MultiSelectFilterConfigV2>) {
  if (!filter.multiSelectProps) return null;
  return (
    <MultiSelect
      {...filter.multiSelectProps}
      value={value as string[]}
      onChange={(v) => onChange(v)}
      className={cn(layout === 'row' ? 'w-50' : 'w-full', filter.multiSelectProps.className)}
      disabled={filter.disable}
    />
  );
}

function TreeSelectFilter({ filter, value, onChange }: RendererProps<TreeSelectFilterConfig>) {
  if (!filter.treeSelectProps) return null;
  return (
    <TreeSelect
      {...filter.treeSelectProps}
      value={value as string}
      onChange={(v) => onChange(v ?? '')}
      className={cn('w-50', filter.treeSelectProps.className)}
      disabled={filter.disable}
    />
  );
}

function TreeMultipleSelectFilter({
  filter,
  value,
  onChange,
}: RendererProps<TreeMultipleSelectFilterConfig>) {
  if (!filter.treeMultipleSelectProps) return null;
  return (
    <TreeMultipleSelect
      {...filter.treeMultipleSelectProps}
      value={value as string[]}
      onChange={(v) => onChange(v ?? [])}
      className={cn('w-50', filter.treeMultipleSelectProps.className)}
      disabled={filter.disable}
    />
  );
}

function DatePickerFilter({
  filter,
  value,
  onChange,
  layout,
}: RendererProps<DatePickerFilterConfigV2>) {
  const content = (
    <DatePicker
      outputFormat="iso"
      showPresets
      showActions
      {...filter.datePickerProps}
      value={value as DateValue}
      onChange={(v) => {
        onChange(v);
        filter.onChange?.(v);
      }}
      disabled={filter.disable}
    />
  );
  return layout === 'row' ? <div className="w-fit">{content}</div> : content;
}

function DateRangePickerFilter({
  filter,
  value,
  onChange,
  layout,
}: RendererProps<DateRangePickerFilterConfigV2>) {
  const content = (
    <DateRangePicker
      key={`${filter.key}-${filter.dateRangePickerProps?.defaultMode ?? 'date'}`}
      outputFormat="iso"
      showPresets
      showActions
      {...filter.dateRangePickerProps}
      value={value as DateRange}
      onChange={(v, meta) => {
        onChange(v);
        filter.onChange?.(v, meta);
      }}
      disabled={filter.disable}
    />
  );
  return layout === 'row' ? <div className="w-fit">{content}</div> : content;
}

// ---------------------------------------------------------------------------
// Registry
// ---------------------------------------------------------------------------

const FILTER_RENDERERS = {
  tabs: TabsFilter,
  select: AsyncSelectFilter,
  'multi-select': MultiSelectFilter,
  'tree-select': TreeSelectFilter,
  'tree-multiple-select': TreeMultipleSelectFilter,
  'date-picker': DatePickerFilter,
  'date-range-picker': DateRangePickerFilter,
} as const satisfies Record<FilterConfigV2['type'], React.ComponentType<RendererProps<never>>>;

// ---------------------------------------------------------------------------
// Public component
// ---------------------------------------------------------------------------

export type FilterFieldPropsV2 = {
  filter: FilterConfigV2 | AdvancedFilterConfigV2;
  values: Record<string, FilterValueV2>;
  onChange: (key: string, value: FilterValueV2) => void;
  layout: 'row' | 'column';
};

export const FilterField = memo(function FilterField({
  filter,
  values,
  onChange,
  layout,
}: FilterFieldPropsV2) {
  const Component = FILTER_RENDERERS[filter.type] as React.ComponentType<
    RendererProps<typeof filter>
  >;

  if (!Component) return null;

  const wrapperClassName = layout === 'row' ? 'flex items-center gap-2' : 'flex flex-col gap-2';
  const labelClassName =
    layout === 'row'
      ? 'whitespace-nowrap font-medium text-muted-foreground text-sm'
      : 'font-medium text-muted-foreground text-sm';

  return (
    <div className={wrapperClassName}>
      <span className={labelClassName}>{filter.label}:</span>
      <Component
        filter={filter}
        value={values[filter.key]}
        onChange={(value) => onChange(filter.key, value)}
        layout={layout}
      />
    </div>
  );
});

import { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from '../../../ui/overlays/dialog';
import { Button } from '../../../ui/actions/button';
import { Input } from '../../../ui/forms/input';
import { Label } from '../../../ui/display/label';
import { useFilterPanelLocaleV2 } from '../i18n';

interface RenameTemplateDialogPropsV2 {
  open: boolean;
  initialName: string;
  onClose: () => void;
  onRename: (name: string) => void;
}

export function RenameTemplateDialog({
  open,
  initialName,
  onClose,
  onRename,
}: RenameTemplateDialogPropsV2) {
  const locale = useFilterPanelLocaleV2();
  const [name, setName] = useState(initialName);

  // Sync input with initialName whenever dialog opens
  useEffect(() => {
    if (open) setName(initialName);
  }, [open, initialName]);

  const handleRename = () => {
    const trimmed = name.trim();
    if (!trimmed) return;
    onRename(trimmed);
  };

  const handleClose = () => {
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && handleClose()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{locale.renameDialogTitle}</DialogTitle>
          <DialogDescription render={<div />} />
        </DialogHeader>

        <div className="space-y-2 py-2">
          <Label htmlFor="rename-template-name">{locale.templateNameLabel}</Label>
          <Input
            id="rename-template-name"
            placeholder={locale.templateNamePlaceholder}
            value={name}
            onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleRename()}
            maxLength={255}
            autoFocus
          />
        </div>

        <DialogFooter>
          <DialogClose
            render={
              <Button variant="ghost" onClick={handleClose}>
                {locale.cancelLabel}
              </Button>
            }
          />
          <Button onClick={handleRename} disabled={!name.trim() || name.trim().length > 255}>
            {locale.renameLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
  DialogClose,
} from '../../../ui/overlays/dialog';
import { Button } from '../../../ui/actions/button';
import { Input } from '../../../ui/forms/input';
import { Label } from '../../../ui/display/label';
import { useFilterPanelLocaleV2 } from '../i18n';

interface SaveTemplateDialogPropsV2 {
  open: boolean;
  onClose: () => void;
  onSave: (name: string) => void;
}

export function SaveTemplateDialog({ open, onClose, onSave }: SaveTemplateDialogPropsV2) {
  const locale = useFilterPanelLocaleV2();
  const [name, setName] = useState('');

  const handleSave = () => {
    const trimmed = name.trim();
    if (!trimmed) return;
    onSave(trimmed);
    setName('');
  };

  const handleClose = () => {
    setName('');
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && handleClose()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{locale.saveDialogTitle}</DialogTitle>
          <DialogDescription render={<div />}>{locale.saveDialogDescription}</DialogDescription>
        </DialogHeader>

        <div className="space-y-2 py-2">
          <Label htmlFor="template-name">{locale.templateNameLabel}</Label>
          <Input
            id="template-name"
            placeholder={locale.templateNamePlaceholder}
            value={name}
            onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSave()}
            maxLength={255}
            autoFocus
          />
        </div>

        <DialogFooter>
          <DialogClose
            render={
              <Button variant="ghost" onClick={handleClose}>
                {locale.cancelLabel}
              </Button>
            }
          />
          <Button onClick={handleSave} disabled={!name.trim() || name.trim().length > 255}>
            {locale.saveLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Popover, PopoverTrigger, PopoverContent } from '../../../ui/overlays/popover';
import { Button } from '../../../ui/actions/button';
import { cn } from '../../../../lib/utils';
import { ChevronDown, Check, Bookmark, Trash2, Save, PlusCircle, Pencil } from 'lucide-react';
import { formatDate } from '../../../../utils/date';
import type { FilterTemplateDBV2 } from '../hooks/use-persistent-filter-template';
import { useFilterPanelLocaleV2 } from '../i18n';

interface TemplateChipPropsV2 {
  templates: FilterTemplateDBV2[];
  activeTemplateId?: string;
  onSelect: (template: FilterTemplateDBV2) => void;
  onSaveClick: () => void;
  onUpdateClick: () => void;
  onDeleteRequest: (template: FilterTemplateDBV2) => void;
  onRenameRequest: (template: FilterTemplateDBV2) => void;
  hasChangeFilter: boolean;
}

function EmptyTemplateContent() {
  const locale = useFilterPanelLocaleV2();
  return (
    <div className="flex flex-col items-center gap-1.5 px-3 py-6 text-center text-muted-foreground">
      <Bookmark className="size-6 opacity-40" />
      <p className="text-sm">{locale.emptyTemplatesTitle}</p>
      <p className="text-xs">{locale.emptyTemplatesSubtitle}</p>
    </div>
  );
}

interface TemplateChipOptionItemPropsV2 {
  template: FilterTemplateDBV2;
  isActive: boolean;
  onSelect: (template: FilterTemplateDBV2) => void;
  onDeleteRequest: (template: FilterTemplateDBV2) => void;
  onRenameRequest: (template: FilterTemplateDBV2) => void;
  setDropdownOpen: (open: boolean) => void;
}

function TemplateChipOptionItem({
  template,
  isActive,
  onSelect,
  onDeleteRequest,
  onRenameRequest,
  setDropdownOpen,
}: TemplateChipOptionItemPropsV2) {
  return (
    <div
      className={cn(
        'group flex w-full items-center gap-2 rounded-md px-2.5 py-2 text-left text-sm transition-colors',
        isActive
          ? 'bg-primary/10 font-medium text-primary'
          : 'text-popover-foreground hover:bg-accent'
      )}
    >
      <button
        type="button"
        onClick={() => onSelect(template)}
        className="flex min-w-0 flex-1 items-center gap-2"
      >
        <Check className={cn('size-3.5 shrink-0', isActive ? 'text-primary' : 'invisible')} />
        <div className="flex min-w-0 flex-1 flex-col items-start">
          <p className="truncate">{template.name}</p>
          <p className="text-muted-foreground text-xs">
            {formatDate(template.createdAt, 'dd-MM-yyyy HH:mm:ss')}
          </p>
        </div>
      </button>
      <Button
        variant="ghost"
        size="icon-sm"
        className="shrink-0 opacity-0 transition-opacity group-hover:opacity-100"
        onClick={(e) => {
          e.stopPropagation();
          setDropdownOpen(false);
          onRenameRequest(template);
        }}
      >
        <Pencil className="size-3.5 text-muted-foreground" />
      </Button>
      <Button
        variant="ghost"
        size="icon-sm"
        className="shrink-0 opacity-0 transition-opacity group-hover:opacity-100"
        onClick={(e) => {
          e.stopPropagation();
          setDropdownOpen(false);
          onDeleteRequest(template);
        }}
      >
        <Trash2 className="size-3.5 text-destructive" />
      </Button>
    </div>
  );
}

export function TemplateChip({
  templates,
  activeTemplateId,
  onSelect,
  onSaveClick,
  onUpdateClick,
  onDeleteRequest,
  onRenameRequest,
  hasChangeFilter,
}: TemplateChipPropsV2) {
  const locale = useFilterPanelLocaleV2();
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [savePopoverOpen, setSavePopoverOpen] = useState(false);

  const activeTemplate = templates.find((t) => t.id === activeTemplateId);
  const displayName = activeTemplate?.name ?? locale.defaultTemplateName;
  const hasTemplates = templates.length > 0;

  const handleSelect = (template: FilterTemplateDBV2) => {
    onSelect(template);
    setDropdownOpen(false);
  };

  return (
    <div className="flex items-center gap-1.5">
      {/* ── Template selector dropdown ───────────────────────────────── */}
      <Popover open={dropdownOpen} onOpenChange={setDropdownOpen}>
        <PopoverTrigger
          render={
            <button
              type="button"
              className={cn(
                'inline-flex cursor-pointer items-center gap-2 rounded-full border px-3 py-1.5 font-medium text-sm transition-colors',
                activeTemplate
                  ? 'border-primary/30 bg-primary/10 text-primary hover:bg-primary/15'
                  : 'border-border bg-muted text-muted-foreground hover:bg-muted/80'
              )}
            >
              <Bookmark className="size-3.5 shrink-0" />
              <span className="max-w-[160px] truncate">
                {displayName}
                {hasChangeFilter ? <span className="ml-0.5 text-amber-500">*</span> : null}
              </span>
              <ChevronDown
                className={cn(
                  'size-3.5 shrink-0 transition-transform duration-200',
                  dropdownOpen && 'rotate-180'
                )}
              />
            </button>
          }
        />

        <PopoverContent align="start" sideOffset={6} className="w-72 p-0">
          <div className="max-h-[240px] overflow-y-auto">
            {!hasTemplates ? (
              <EmptyTemplateContent />
            ) : (
              <ul className="p-1">
                {templates.map((template) => {
                  const isActive = template.id === activeTemplateId;
                  return (
                    <li key={template.id}>
                      <TemplateChipOptionItem
                        template={template}
                        isActive={isActive}
                        onSelect={handleSelect}
                        onDeleteRequest={onDeleteRequest}
                        onRenameRequest={onRenameRequest}
                        setDropdownOpen={setDropdownOpen}
                      />
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        </PopoverContent>
      </Popover>

      {/* ── Save button (only when filters are dirty) ────────────────── */}
      {/* {hasChangeFilter && ( */}
      <Popover open={savePopoverOpen} onOpenChange={setSavePopoverOpen}>
        <PopoverTrigger
          disabled={!hasChangeFilter}
          render={
            <Button size="sm" variant="default" className="h-8 gap-1.5 rounded-full px-3 text-xs">
              <Save className="size-3.5" />
              {locale.saveButtonLabel}
            </Button>
          }
        />
        <PopoverContent align="start" sideOffset={6} className="w-56 p-1.5">
          <div className="flex flex-col gap-0.5">
            {activeTemplate && (
              <button
                type="button"
                onClick={() => {
                  onUpdateClick();
                  setSavePopoverOpen(false);
                }}
                className="flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-sm transition-colors hover:bg-accent"
              >
                <Save className="size-3.5 shrink-0 text-muted-foreground" />
                <span className="truncate">{locale.updateTemplateLabel(activeTemplate.name)}</span>
              </button>
            )}
            <button
              type="button"
              onClick={() => {
                onSaveClick();
                setSavePopoverOpen(false);
              }}
              className="flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-sm transition-colors hover:bg-accent"
            >
              <PlusCircle className="size-3.5 shrink-0 text-muted-foreground" />
              {locale.saveAsNewLabel}
            </button>
          </div>
        </PopoverContent>
      </Popover>
      {/* )} */}
    </div>
  );
}

import { useMemo, useRef, useState, lazy } from 'react';
import { Button } from '../../ui/actions/button';
import { Badge } from '../../ui/display/badge';
import { Card, CardContent } from '../../ui/display/card';
import { Filter, RotateCcw, X } from 'lucide-react';
import { cn } from '../../../lib/utils';
import { useStickyObserver } from './hooks/use-sticky-observer';
import { useTemplateManager } from './hooks/use-template-manager';
import { countSelectedAdvancedFilters } from './utils/filter-value';
import type { FilterPanelPropsV2, AdvancedFilterGroupV2 } from './types';
import { getGridClasses } from './utils/grid';
import { FilterField } from './components/filter-field';
import { TemplateChip } from './components/template-chip';
import { defaultFilterPanelLocaleV2, FilterPanelLocaleContextV2 } from './i18n';

const SaveTemplateDialog = lazy(() =>
  import('./components/save-template-dialog').then((mod) => ({ default: mod.SaveTemplateDialog }))
);
const DeleteTemplateDialog = lazy(() =>
  import('./components/delete-template-dialog').then((mod) => ({
    default: mod.DeleteTemplateDialog,
  }))
);
const RenameTemplateDialog = lazy(() =>
  import('./components/rename-template-dialog').then((mod) => ({
    default: mod.RenameTemplateDialog,
  }))
);

export function FilterPanelV2({
  filters,
  advancedFilters = [],
  advancedFilterGroups,
  values,
  defaultValues = {},
  onChange,
  onReset,
  advancedFiltersLabel = 'Advanced Filters',
  advancedFiltersButton,
  resetLabel,
  className,
  contentClassName,
  renderAfterFilters,
  primaryFiltersColumns,
  advancedFiltersColumns,
  disable,
  children,
  stickyOffsetTop = 'top-16',
  stickyBg = 'bg-white',
  stickyClassName = '-mx-4',
  isSticky = true,
  module,
  onApplyTemplate,
  onActiveTemplateChange,
  locale,
}: FilterPanelPropsV2) {
  const resolvedLocale = { ...defaultFilterPanelLocaleV2, ...locale };
  const [showAdvanced, setShowAdvanced] = useState(false);
  const advancedRef = useRef<HTMLDivElement>(null);
  const { sentinelRef, isStuck: rawIsStuck } = useStickyObserver();
  const isStuck = isSticky && rawIsStuck;

  // ── Template management ─────────────────────────────────────────────
  const templateManager = useTemplateManager({
    module,
    values,
    defaultValues,
    onApplyTemplate,
    onActiveTemplateChange,
    locale: resolvedLocale,
  });

  // Compute effective groups (prioritize advancedFilterGroups)
  const effectiveGroups: AdvancedFilterGroupV2[] = useMemo(() => {
    if (advancedFilterGroups && advancedFilterGroups.length > 0) {
      return advancedFilterGroups;
    }
    if (advancedFilters && advancedFilters.length > 0) {
      // Wrap flat list in single group with empty title
      return [{ title: '', filters: advancedFilters }];
    }
    return [];
  }, [advancedFilterGroups, advancedFilters]);

  // Flat list of all advanced filters for calculations
  const allAdvancedFilters = useMemo(
    () => effectiveGroups.flatMap((g) => g.filters),
    [effectiveGroups]
  );

  // Check if there are any advanced filters
  const hasAdvancedFilters = effectiveGroups.length > 0 && allAdvancedFilters.length > 0;
  // Count selected advanced filters that differ from default values
  const selectedAdvancedCount = useMemo(
    () =>
      countSelectedAdvancedFilters({
        allAdvancedFilters,
        values,
        defaultValues,
      }),
    [allAdvancedFilters, values, defaultValues]
  );

  const handleReset = () => {
    setShowAdvanced(false);
    onReset?.(templateManager.activeTemplate?.filters);
  };

  return (
    <FilterPanelLocaleContextV2.Provider value={resolvedLocale}>
      {isSticky && <div ref={sentinelRef} className="mb-0 h-0" />}
      <Card
        className={cn(
          isSticky && `sticky ${stickyOffsetTop} z-30`,
          'transition-[border-radius,margin] duration-200',
          isStuck && 'rounded-none',
          isStuck && stickyBg,
          isStuck && stickyClassName,
          className
        )}
      >
        <CardContent className="flex flex-col gap-4">
          {templateManager.enabled && (
            <div className="flex flex-col gap-1">
              <p className="font-medium text-muted-foreground text-sm">
                {resolvedLocale.savedTemplatesLabel}
              </p>
              <TemplateChip
                templates={templateManager.templates}
                activeTemplateId={templateManager.activeTemplateId}
                onSelect={templateManager.handleSelect}
                onSaveClick={templateManager.openSaveDialog}
                onUpdateClick={templateManager.handleUpdate}
                onDeleteRequest={templateManager.handleRequestDelete}
                onRenameRequest={templateManager.handleRequestRename}
                hasChangeFilter={templateManager.hasChangeFilter}
              />
            </div>
          )}
          {/* Main Filters */}
          <div className={cn('item-start flex justify-between', contentClassName)}>
            {/* Template chip — inline before filters */}
            <div
              className={cn(
                primaryFiltersColumns
                  ? getGridClasses(primaryFiltersColumns, 'flex flex-wrap items-center')
                  : 'flex flex-wrap items-center',
                'gap-4'
              )}
            >
              {filters.map((filter) => (
                <FilterField
                  key={filter.key}
                  filter={filter}
                  values={values}
                  onChange={onChange}
                  layout="row"
                />
              ))}

              {/* Custom content after main filters */}
              {renderAfterFilters}
            </div>
            {/* Template, Advanced Filters Toggle & Reset */}
            {(hasAdvancedFilters || onReset) && (
              <div className="flex items-start justify-end gap-2">
                {onReset && (
                  <Button
                    disabled={disable}
                    variant="ghost"
                    size="sm"
                    onClick={handleReset}
                    className="gap-2"
                  >
                    <RotateCcw className="h-4 w-4" />
                    {resetLabel}
                  </Button>
                )}
                {hasAdvancedFilters && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setShowAdvanced(!showAdvanced)}
                    className="relative gap-2"
                    data-advanced-filter-toggle
                  >
                    <Filter className="h-4 w-4" />
                    {advancedFiltersButton}
                    {selectedAdvancedCount > 0 && (
                      <Badge
                        variant="primary"
