   * - object: Responsive columns (e.g., { sm: 1, md: 2, lg: 4 })
   * Default: flex wrap layout (no grid)
   */
  primaryFiltersColumns?: ColumnFilterPanelConfigV2;

  /**
   * Grid columns for advanced filters section
   * - number: Fixed columns (e.g., 3)
   * - object: Responsive columns (e.g., { sm: 1, md: 2, lg: 3 })
   * Default: grid-cols-1 md:grid-cols-2
   */
  advancedFiltersColumns?: ColumnFilterPanelConfigV2;
  disable?: boolean;

  /**
   * Content rendered inside the Card below filters (e.g. always-visible required fields)
   */
  children?: React.ReactNode;

  /**
   * Tailwind top class for sticky positioning (e.g. 'top-0', 'top-16')
   * @default 'top-0'
   */
  stickyOffsetTop?: string;

  /**
   * Background class applied when the panel is stuck (e.g. 'bg-background')
   */
  stickyBg?: string;

  /**
   * Additional className applied only when the panel is stuck (e.g. '-mx-4')
   */
  stickyClassName?: string;

  /**
   * Enable sticky behavior (sentinel + IntersectionObserver)
   * @default true
   */
  isSticky?: boolean;

  // ─── Template feature (opt-in) ──────────────────────────────────────

  /**
   * Module identifier that scopes templates in IndexedDB.
   * When provided, enables the template save/load feature.
   */
  module?: string;

  /**
   * Called when a template is applied — either by user selection from the
   * drawer or auto-applied on mount (latest template).
   * The parent should use this to update its controlled `values` state.
   */
  onApplyTemplate?: (filters: Record<string, FilterValueV2>) => void;

  /**
   * Called whenever the active template changes (selection, auto-apply on
   * mount, or deletion). Receives `undefined` when no template is active.
   * Use this to read the current active template's metadata/filters externally.
   */
  onActiveTemplateChange?: (template: FilterTemplateDBV2 | undefined) => void;

  /**
   * Partial locale overrides for all hardcoded strings inside the filter panel.
   * Only supply the keys you want to translate — the rest fall back to English defaults.
   *
   * @example
   * ```tsx
   * // Using next-intl
   * locale={{
   *   savedTemplatesLabel: t('filter.savedTemplates'),
   *   saveButtonLabel: t('common.save'),
   *   cancelLabel: t('common.cancel'),
   *   deleteDialogDescription: (name) => t('filter.deleteConfirm', { name }),
   *   templateUpdatedToast: (name) => t('filter.templateUpdated', { name }),
   * }}
   * ```
   */
  locale?: Partial<FilterPanelLocaleV2>;
}

import type { AdvancedFilterConfigV2, FilterValueV2 } from '../types';
import type { DateRange } from '../../date-picker';

// Helper to check if a filter value is "selected" (non-empty) and should count.
export function isNonEmptyFilterValue(value: FilterValueV2 | undefined): boolean {
  if (!value) return false;
  if (Array.isArray(value)) return value.length > 0;

  // DateRange check: expected shape { from, to }
  if (typeof value === 'object' && 'from' in value && 'to' in value) {
    const range = value as DateRange;
    return Boolean(range.from || range.to);
  }

  // DateValue check
  if (typeof value === 'string') return value !== '';
  if (value instanceof Date) return true;
  return false;
}

// Helper to compare filter values (used to avoid counting "defaults" as selected).
export function areFilterValuesEqual(
  a: FilterValueV2 | undefined,
  b: FilterValueV2 | undefined
): boolean {
  // Array comparison (multi-select) - order-sensitive (matches existing behavior)
  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((v, i) => v === b[i]);
  }

  // DateRange comparison
  if (
    typeof a === 'object' &&
    a !== null &&
    'from' in a &&
    typeof b === 'object' &&
    b !== null &&
    'from' in b
  ) {
    const aRange = a as DateRange;
    const bRange = b as DateRange;
    const aFrom = aRange.from instanceof Date ? aRange.from.getTime() : aRange.from;
    const bFrom = bRange.from instanceof Date ? bRange.from.getTime() : bRange.from;
    const aTo = aRange.to instanceof Date ? aRange.to.getTime() : aRange.to;
    const bTo = bRange.to instanceof Date ? bRange.to.getTime() : bRange.to;
    return aFrom === bFrom && aTo === bTo;
  }

  // Date comparison
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // Primitive comparison (string, undefined)
  return a === b;
}

export function countSelectedAdvancedFilters({
  allAdvancedFilters,
  values,
  defaultValues,
}: {
  allAdvancedFilters: AdvancedFilterConfigV2[];
  values: Record<string, FilterValueV2>;
  defaultValues: Record<string, FilterValueV2>;
}): number {
  return allAdvancedFilters.filter((filter) => {
    const currentValue = values[filter.key];
    const defaultValue = defaultValues[filter.key];
    const isDifferent =
      isNonEmptyFilterValue(currentValue) && !areFilterValuesEqual(currentValue, defaultValue);
    return isDifferent;
  }).length;
}

import type { ColumnFilterPanelConfigV2 } from '../types';

/**
 * Generates Tailwind grid column classes from column config
 * @param config - Column configuration (number or responsive object)
 * @param defaultClasses - Default classes when config not provided
 * @returns Tailwind class string
 */
export function getGridClasses(
  config: ColumnFilterPanelConfigV2 | undefined,
  defaultClasses: string
): string {
  if (config === undefined) {
    return defaultClasses;
  }

  if (typeof config === 'number') {
    return `grid grid-cols-${config}`;
  }

  const classes: string[] = ['grid'];

  // Base (mobile-first)
  if (config.sm !== undefined) {
    classes.push(`grid-cols-${config.sm}`);
  } else {
    classes.push('grid-cols-1');
  }

  // Responsive breakpoints
  if (config.md !== undefined) {
    classes.push(`md:grid-cols-${config.md}`);
  }
  if (config.lg !== undefined) {
    classes.push(`lg:grid-cols-${config.lg}`);
  }
  if (config.xl !== undefined) {
    classes.push(`xl:grid-cols-${config.xl}`);
  }
  if (config['2xl'] !== undefined) {
    classes.push(`2xl:grid-cols-${config['2xl']}`);
  }

  return classes.join(' ');
}
